import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    for _ in range(n-1):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        adj[v].append(u)
    attacked = list(map(int, sys.stdin.readline().split()))

    def bfs(start):
        dist = [-1]*(n+1)
        q = deque()
        q.append(start)
        dist[start] = 0
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        return dist

    dists = [bfs(city) for city in attacked]
    max_dist = [0]*n
    for dist in dists:
        for i in range(1, n+1):
            if dist[i] != -1:
                max_dist[i] = max(max_dist[i], dist[i])

    min_time = float('inf')
    best_city = 1
    for city in range(1, n+1):
        if max_dist[city] < min_time:
            min_time = max_dist[city]
            best_city = city
        elif max_dist[city] == min_time and city < best_city:
            best_city = city
    print(best_city)
    print(min_time)

main()
